  // formatter over every other line - so the one thing checked here is that
  // it still lists what was just written, in the same order.
  const listed = (MANIFEST.Profiles ?? []).map((p) => `${p.Name}:${p.DeviceType}:${p.AutoInstall}`).join(" ");
