  if (listed !== expected) throw new Error(`manifest.json lists\n  ${listed}\nbut this wrote\n  ${expected}`);

  console.log(`${written.length} profiles written to ${dir}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();

